const ICON={tv:'M4 7h16v11H4zM8 3l4 4 4-4',refresh:'M20 11a8 8 0 1 0-2.3 5.7M20 5v6h-6',qr:'M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h2v2h-2zM18 18h2v2h-2zM14 18h2',play:'M8 5v14l11-7z',pause:'M7 5h4v14H7zM13 5h4v14h-4z',stop:'M6 6h12v12H6z',plus:'M12 5v14M5 12h14',send:'M4 12l16-8-6 16-3-7z',x:'M6 6l12 12M18 6L6 18',ext:'M14 4h6v6M20 4l-9 9M18 14v6H4V6h6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18zM12 7v5l3 2',sliders:'M4 6h9M17 6h3M4 12h3M11 12h9M4 18h11M19 18h1M15 4v4M9 10v4M17 16v4',check:'M5 12l5 5 9-10',minus:'M6 12h12',more:'M5 12h.01M12 12h.01M19 12h.01'};
