const ROLE_MODEL_REQUIRED=['观看角色尚未连接聊天模型，请到 AI 酱中检查该角色的模型绑定或默认聊天连接。','The viewing character has no chat model connection. Check the character’s model binding or default chat connection in AI Buddy.'];
const ROLE_IMAGE_UNSUPPORTED=['本次阅读模型未确认支持图片。请到 AI 酱中检查观看角色的模型绑定与 API 配置。停止旧阅读后再使用支持图片的聊天连接开始新阅读，不会自动换模型。','The model for this reading is not confirmed to support images. Check the viewing character’s model binding and API settings in AI Buddy. Stop the old reading before starting a new one with an image-capable chat connection; the model will not switch automatically.'];
const MESSAGES={SOCIAL_LOGIN_EXPIRED:['B站登录已过期，请重新扫码连接。','The Bilibili login expired. Scan again to reconnect.'],SOCIAL_LOGIN_IDENTITY_MISMATCH:['B站账号不一致，请重新扫码连接。','The Bilibili account does not match. Scan again to reconnect.'],SOCIAL_LOGIN_NETWORK_ERROR:['暂时无法核对B站登录，请检查网络后重试；这不代表账号已退出。','Could not verify the Bilibili login. Check the network and retry; this does not mean you signed out.'],SOCIAL_LOGIN_BUSY:['请先完成或取消正在进行的扫码。','Finish or cancel the current QR login first.'],SOCIAL_LOGIN_VERIFICATION_REQUIRED:['当前宿主无法核对B站登录，请更新 AI 酱后重试。','This host cannot verify the Bilibili login. Update AI Buddy and retry.'],BILI_QUOTA_EXHAUSTED:['今天的额度用完了。','Today’s allowance is used up.'],BILI_COMMENTS_OFF:['评论现在是关闭的，先在设置里打开。','Comments are off. Turn them on in Settings.'],BILI_PAUSED:['观看已暂停，先点「继续」。','Watching is paused. Press Continue first.'],BILI_STOPPED:['观看已停止，可以重新点「现在看」。','Watching was stopped. Start again with Watch now.'],BILI_OUTSIDE_WINDOW:['现在不在允许观看的时间段里。','This is outside the allowed watching hours.'],BILI_TODAY_FORBIDDEN:['今天设成了不看。','Watching is turned off for today.'],BILI_SLEEPING:['她睡着了，醒来后再说。','She is asleep. Try again when she wakes.'],BILI_CHARACTER_REQUIRED:['先选参与角色。','Pick a character first.'],BILI_CONNECTION_REQUIRED:['先在设置里选一个 B站账号。','Choose a Bilibili account in Settings first.'],BILI_MODEL_REQUIRED:ROLE_MODEL_REQUIRED,BILI_VISION_MODEL_REQUIRED:ROLE_MODEL_REQUIRED,BILI_VISION_MODEL_UNSUPPORTED:ROLE_IMAGE_UNSUPPORTED,BILI_COMMENT_PREVIEW_REQUIRED:['评论设成了先预览再发，请先预览。','Comments are set to preview first.'],BILI_COMMENT_EXPIRED:['只能给今天看的视频发评论。','Only today’s videos can get a comment.'],BILI_CONCURRENCY_LIMIT:['同时观看的人数已满。','The watching-together limit is reached.'],BILI_CONTROL_STALE:['安排刚刚变过，请刷新后再试。','The plan just changed. Refresh and try again.'],BILI_COMMENT_CONSENT_REQUIRED:['开启评论需要明确授权。','Turning comments on needs your explicit permission.'],
  SOCIAL_ACCOUNT_REQUIRED:['先扫码连接一个 B站账号。','Connect a Bilibili account by QR first.'],SOCIAL_ACCOUNT_CHANGED:['B站账号刚刚变了，请刷新。','The Bilibili account just changed. Refresh.'],BILI_SCHEDULE_NOT_STARTABLE:['这个预约现在不能开始。','This plan cannot start now.'],BILI_SCHEDULE_BUSY:['这个预约已经有一个视频在看或暂停着，先点「继续」。','This plan already has a video in progress or paused. Press Continue.'],BILI_SCHEDULE_RUNNING:['先暂停或停止正在看的视频。','Pause or stop the video that is playing first.'],BILI_NOT_FOUND:['没找到这条记录，请刷新。','That item was not found. Refresh.'],BILI_AUTONOMOUS_DISABLED:['还没允许按安排观看。','Watching on schedule is not allowed yet.'],BILI_SCHEDULE_CONFIRM_REQUIRED:['指定视频预约重启后需确认。','Confirm specific-video plans after restarting.'],BILI_SCHEDULE_INVALID:['预约内容不正确，请检查时间、角色和视频。','Check the plan’s time, characters and video.']};
const SCHEDULE={scheduled:['已安排','Planned','info'],running:['观看中','Watching','busy'],paused:['已暂停','Paused','warn'],'waiting-sleep':['等她醒来','Waiting for her to wake','muted'],done:['看完了','Watched','ok'],completed:['看完了','Watched','ok'],failed:['没看成','Not watched','err'],cancelled:['已取消','Cancelled','muted']};
