const MISSED={BILI_SELECTION_EMPTY:['没找到可看的视频','No video to watch was found'],BILI_VIDEO_UNAVAILABLE:['视频打不开或已下架','The video is unavailable'],BILI_VIDEO_INVALID:['视频编号不对','The video ID is not valid'],BILI_HTTP_FAILED:['B站没有回应','Bilibili did not answer'],BILI_RESPONSE_INVALID:['B站的回应读不懂','Bilibili sent an unreadable answer'],BILI_CANCELLED:['被打断了','It was interrupted'],BILI_STOPPED:['你停止了观看','You stopped watching'],BILI_LEASE_REVOKED:['许可在中途变了','Permission changed midway'],SOCIAL_ACTIVITY_DEFERRED:['她当时在忙或在睡','She was busy or asleep'],BILI_OUTSIDE_WINDOW:['超出了允许的时间','It ran past the allowed hours'],BILI_SCHEDULE_EXPIRED:['预约已过期','The plan expired']};
// The four steps of a viewing, for the progress bar of the one going on now.
const STEPS=[['selecting','正在挑视频','Picking a video'],['acquiring-material','正在取视频材料','Loading the video'],['understanding','正在看','Watching'],['recording','正在记录','Taking notes']];
const stepOf=a=>{const i=STEPS.findIndex(s=>s[0]===a.state);return i>=0?i:!a.video?0:!a.material?1:!a.understanding?2:3;};
