// AI Buddy can show this page inside its main window, where Bilibili and QQ share one DSH page that opens on DSH's
// own panel. Only plugin code may switch panels, so the host names a plugin (data-buddy-open-plugin on <html>, then
// "ai-buddy:open-plugin-page") and waits for that plugin to answer with data-buddy-panel once its panel is selected.
function bindBuddyPanel(ctx){
  const view=globalThis.window,root=()=>globalThis.document?.documentElement;
  const select=()=>{const data=root()?.dataset;try{ctx.layout.selectPanel(PANEL_KEY);if(data)data.buddyPanel=CLIENT_PLUGIN_ID;}catch{if(data?.buddyPanel===CLIENT_PLUGIN_ID)delete data.buddyPanel;}};
  const listener=event=>{if(event?.detail?.pluginId!==CLIENT_PLUGIN_ID)return;if(!livePages)pendingActivity=activityTarget({detail:event.detail})??pendingActivity;select();};
  const readingListener=event=>{const id=event.detail?.activityId;if(typeof id!=='string'||! /^[a-zA-Z0-9:_-]{1,160}$/.test(id))return;if(!livePages)pendingReading=id;select();};
  view?.addEventListener?.('ai-buddy:bili-reading-open',readingListener);
  view?.addEventListener?.('ai-buddy:open-plugin-page',listener);
  if(root()?.dataset?.buddyOpenPlugin===CLIENT_PLUGIN_ID)select();
  return()=>{view?.removeEventListener?.('ai-buddy:open-plugin-page',listener);view?.removeEventListener?.('ai-buddy:bili-reading-open',readingListener);};
}
